INSERT INTO `posts` VALUES (1,889,1,NULL,'Rentrée scolaire 2025-2026 — Bienvenue !','Chères familles, chers élèves et chers professeurs,\n\nC\'est avec un immense plaisir que nous vous accueillons pour cette nouvelle année scolaire à Lycée Al Kindi. Cette année s\'annonce riche en projets, en défis et en réussites. Ensemble, nous visons l\'excellence.\n\nBonne rentrée à toutes et à tous !',1,1,'school',NULL,0,70,15,15,'2026-05-29 11:31:37','2026-05-31 20:31:37',NULL),(2,889,1,NULL,'Résultats du 1er trimestre — Félicitations !','Les résultats du premier trimestre sont disponibles sur l\'espace numérique. La moyenne générale de l\'établissement est en hausse de 0,8 point par rapport à l\'année dernière. Félicitations à tous les élèves et un grand merci aux enseignants pour leur engagement.',0,1,'school',NULL,0,51,11,10,'2026-05-30 14:31:37','2026-05-31 20:31:37',NULL),(3,889,1,NULL,NULL,'Rappel important : les demandes d\'attestations de scolarité sont à déposer au secrétariat avant le vendredi 15 mai. Merci de vous munir de votre carte d\'étudiant.',0,1,'school',NULL,0,29,4,10,'2026-05-28 06:31:37','2026-05-31 20:31:37',NULL),(4,890,1,1,'DM n°8 — Physique','Voici le devoir maison n°8 à rendre pour le lundi 02 Jun.\n\nExercices prioritaires : 1 et 8. La correction sera projetée en classe la semaine suivante. Bon courage !',0,0,'group',NULL,0,27,13,4,'2026-05-26 08:31:37','2026-05-31 20:31:37',NULL),(5,890,1,1,NULL,'Rappel : contrôle de physique lundi 03 Jun. Chapitres concernés : Électricité — Régimes transitoires. Les fiches de révision sont disponibles dans l\'espace classe.',0,0,'group',NULL,0,20,10,5,'2026-05-28 05:31:37','2026-05-31 20:31:37',NULL),(6,890,1,1,NULL,'Bonjour à tous ! Voici le compte-rendu du TP de mathématiques n°3. Merci de corriger vos erreurs avant la prochaine séance. N\'hésitez pas à poser vos questions en commentaire.',0,0,'group',NULL,0,36,13,10,'2026-05-29 15:31:37','2026-05-31 20:31:37',NULL),(7,890,1,1,'Ressources — Chapitre 4','Je partage ici les ressources complémentaires pour le chapitre 4. Ces documents vous aideront à approfondir les notions vues en cours. Bonne lecture !',0,0,'group',NULL,0,43,6,9,'2026-05-26 08:31:37','2026-05-31 20:31:37',NULL),(8,891,1,2,'DM n°3 — Anglais','Voici le devoir maison n°3 à rendre pour le lundi 02 Jun.\n\nExercices prioritaires : 1 et 8. La correction sera projetée en classe la semaine suivante. Bon courage !',0,0,'group',NULL,0,28,15,8,'2026-05-28 19:31:37','2026-05-31 20:31:38',NULL),(9,891,1,2,NULL,'Rappel : contrôle de svt lundi 03 Jun. Chapitres concernés : Narration et temps grammaticaux. Les fiches de révision sont disponibles dans l\'espace classe.',0,0,'group',NULL,0,17,8,5,'2026-05-28 07:31:37','2026-05-31 20:31:38',NULL),(10,891,1,2,NULL,'Bonjour à tous ! Voici le compte-rendu du TP de anglais n°3. Merci de corriger vos erreurs avant la prochaine séance. N\'hésitez pas à poser vos questions en commentaire.',0,0,'group',NULL,0,19,15,7,'2026-05-26 22:31:37','2026-05-31 20:31:38',NULL),(11,892,1,3,'DM n°6 — économie','Voici le devoir maison n°6 à rendre pour le lundi 02 Jun.\n\nExercices prioritaires : 4 et 7. La correction sera projetée en classe la semaine suivante. Bon courage !',0,0,'group',NULL,0,17,9,9,'2026-05-25 21:31:37','2026-05-31 20:31:38',NULL),(12,892,1,3,NULL,'Rappel : contrôle de physique lundi 03 Jun. Chapitres concernés : Littérature du XXe siècle. Les fiches de révision sont disponibles dans l\'espace classe.',0,0,'group',NULL,0,29,14,6,'2026-05-31 18:31:37','2026-05-31 20:31:38',NULL),(13,892,1,3,NULL,'Bonjour à tous ! Voici le compte-rendu du TP de svt n°7. Merci de corriger vos erreurs avant la prochaine séance. N\'hésitez pas à poser vos questions en commentaire.',0,0,'group',NULL,0,40,14,6,'2026-05-26 06:31:37','2026-05-31 20:31:38',NULL),(14,896,1,4,'DM n°6 — Histoire','Voici le devoir maison n°6 à rendre pour le lundi 02 Jun.\n\nExercices prioritaires : 3 et 6. La correction sera projetée en classe la semaine suivante. Bon coura